The problem is that the `useEffect` hook that fetches the data is missing a dependency array.  
Because the effect runs on every render, the component keeps re‑fetching the data, which
causes the UI to flicker and the loading state to never settle.

**Fix**

Add an empty dependency array to the effect so it runs only once when the component mounts.

```tsx
import { useEffect, useState } from "react";
import { getAllUsers } from "../services/userService";

export const Users = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const data = await getAllUsers();
        setUsers(data);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, []);

